enum class Status : std::uint8_t {
    ready,
    module_not_found,
    invalid_image,
    unsupported_build,
    sha256_unavailable,
    sha256_mismatch,
};

struct ModuleIdentity {
    std::uint16_t machine = 0;
    std::uint32_t timestamp = 0;
    std::uint32_t image_base = 0;
    std::uint32_t image_size = 0;
};

const char* status_name(Status status) noexcept;

class Context {
public:
    // The identity must describe the already-loaded target module.
    // The PE header at module_base must match it; without
    // loader_sha256, only this in-memory identity is checked.
    static Context from_module(
        std::uintptr_t module_base,
        ModuleIdentity identity,
        const char* loader_sha256 = nullptr) noexcept;
    // Validates the current process main module and its on-disk SHA-256.
    static Context current_process() noexcept;

    bool ready() const noexcept
    {
        return status_ == Status::ready;
    }

    explicit operator bool() const noexcept
    {
        return ready();
    }

    Status status() const noexcept
    {
        return status_;
    }

    bool file_sha256_verified() const noexcept
    {
        return file_sha256_verified_;
    }

    std::uintptr_t module_base() const noexcept
    {
        return module_base_;
    }

    ModuleIdentity identity() const noexcept
    {
        return identity_;
    }

    // Returns zero unless the context is ready and the RVA is in-image.
    std::uintptr_t resolve_rva(
        std::uint32_t rva) const noexcept;
    template <typename Fn>
    Fn resolve_function(std::uint32_t rva) const noexcept
    {
        return reinterpret_cast<Fn>(resolve_rva(rva));
    }

    // Game-owned global; read again on each call, nullable and non-owning.
    std::uintptr_t game_app_slot() const noexcept;
    CGameApp* game_app() const noexcept;
    // Exact CTrackMania::GetPlayground view; nullable and non-owning.
    // Reacquire on use: lifecycle sampling observed null and replacement.
    CGamePlayground* playground() const noexcept;
    // Exact CTrackMania::GetTmBlockEditor view; nullable and
    // non-owning. This does not claim active-editor semantics.
    CTrackManiaEditor* block_editor() const noexcept;
    // Game-owned service; nullable and non-owning.
    CAudioPort* audio_port() const noexcept;
    // Game-owned input service; nullable and non-owning.
    CInputPort* input_port() const noexcept;

private:
    Status status_ = Status::module_not_found;
    bool file_sha256_verified_ = false;
    std::uintptr_t module_base_ = 0;
    ModuleIdentity identity_{};
};

